def reverse_string(s):
    try:
        if not isinstance(s, str):
            raise TypeError("Input must be a string")
    except TypeError as err:
        print(f"Error: {err}")
        return None

    try:
        if not s:
            return ""
    except Exception as err:
        print(f"Unexpected error when checking for empty string: {err}")
        return None

    try:
        reversed_chars = []
    except Exception as err:
        print(f"Error initializing list: {err}")
        return None

    try:
        for char in s:
            try:
                reversed_chars.insert(0, char)
            except IndexError as err:
                print(f"Error inserting character at index 0: {err}")
                return None
    except TypeError as err:
        print(f"Error iterating through string: {err}")
        return None

    try:
        return "".join(reversed_chars)
    except TypeError as err:
        print(f"Error joining characters: {err}")
        return None
    except Exception as err:
        print(f"An unexpected error occurred during string join: {err}")
        return None

