def count_vowels(text):
    if not isinstance(text, str):
        try:
            raise TypeError("Input must be a string.")
        except TypeError as err:
            print(f"Error: {err}")
            return -1

    vowels = "aeiou"
    count = 0
    for char in text:
        try:
            if char.lower() in vowels:
                count += 1
        except AttributeError as err:
            print(f"Error processing character: {err}")
            continue
        except TypeError as err:
            print(f"Error during comparison: {err}")
            continue
    try:
        return count
    except Exception as err:
        print(f"Unexpected error returning count: {err}")
        return -1

