def calculate_factorial(n):
    try:
        n_int = int(n)
    except ValueError as err:
        raise ValueError(f"Input must be an integer: {err}")

    try:
        if n_int < 0:
            raise ValueError("Input must be a non-negative integer.")
    except ValueError as err:
        print(f"Error: {err}")
        return None

    if n_int == 0:
        return 1

    result = 1
    try:
        for i in range(1, n_int + 1):
            try:
                result *= i
            except TypeError as err:
                raise TypeError(f"Cannot multiply with non-numeric type: {err}")
    except TypeError as err:
        print(f"Calculation error: {err}")
        return None

    try:
        if not isinstance(result, int):
            raise TypeError("Factorial result is not an integer.")
    except TypeError as err:
        print(f"Result validation error: {err}")
        return None

    try:
        if result < 0 and n_int > 0: # Check for unexpected negative results
            raise ValueError("Unexpected negative factorial result.")
    except ValueError as err:
        print(f"Result integrity error: {err}")
        return None

    return result

