def sum_list(numbers):
    total = 0
    try:
        if not isinstance(numbers, list):
            raise TypeError("Input must be a list.")
    except TypeError as err:
        print(f"Error: {err}")
        return None

    for item in numbers:
        try:
            total += item
        except TypeError as err:
            print(f"Skipping non-numeric item due to: {err}")
            continue
        except Exception as err:
            print(f"An unexpected error occurred with item: {item}. Error: {err}")
            continue
    try:
        return total
    except Exception as err:
        print(f"Error returning total: {err}")
        return None

def main():
    try:
        result1 = sum_list([1, 2, 3, 4])
        print(f"Sum of [1, 2, 3, 4]: {result1}")
    except Exception as err:
        print(f"An error occurred during sum_list([1, 2, 3, 4]): {err}")

    try:
        result2 = sum_list([])
        print(f"Sum of []: {result2}")
    except Exception as err:
        print(f"An error occurred during sum_list([]): {err}")

