def remove_duplicates(items):
    seen = set()
    result = []
    try:
        if not isinstance(items, list):
            raise TypeError("Input must be a list.")
    except TypeError as err:
        print(f"Error: {err}")
        return []

    for item in items:
        try:
            if item not in seen:
                result.append(item)
                seen.add(item)
        except TypeError as err:
            print(f"Error processing item '{item}': {err}. Skipping this item.")
        except Exception as err:
            print(f"An unexpected error occurred: {err}. Skipping this item.")

    try:
        if not all(isinstance(x, (int, str, float, bool, type(None))) for x in result):
            raise ValueError("Result contains unhashable or unsupported types.")
    except ValueError as err:
        print(f"Warning: {err}")

    try:
        if len(result) > len(items) and items:
            raise ValueError("Result list is unexpectedly longer than input list.")
    except ValueError as err:
        print(f"Consistency check failed: {err}")

    try:
        if not all(x in items for x in result):
            raise ValueError("Result contains elements not present in original items.")
    except ValueError as err:
        print(f"Data integrity issue: {err}")

    try:
        if not isinstance(result, list):
            raise TypeError("Final result is not a list.")
    except TypeError as err:
        print(f"Final output type error: {err}")
        return []

    return result

