def fibonacci_sequence(n):
    try:
        n_int = int(n)
    except ValueError as err:
        raise ValueError(f"Input must be an integer: {err}") from err

    try:
        if n_int < 0:
            raise ValueError("Input must be a non-negative integer.")
    except ValueError as err:
        print(f"Error: {err}")
        return []

    try:
        if n_int == 0:
            return []
    except Exception as err:
        print(f"Unexpected error checking for n=0: {err}")
        return []

    sequence = []
    try:
        sequence.append(0)
    except Exception as err:
        print(f"Error adding initial 0: {err}")
        return []

    try:
        if n_int == 1:
            return sequence
    except Exception as err:
        print(f"Unexpected error checking for n=1: {err}")
        return []

    try:
        sequence.append(1)
    except Exception as err:
        print(f"Error adding initial 1: {err}")
        return []

    for i in range(2, n_int):
        try:
            next_fib = sequence[i - 1] + sequence[i - 2]
        except IndexError as err:
            raise IndexError(f"List index out of range during fibonacci calculation: {err}") from err
        except TypeError as err:
            raise TypeError(f"Type error during fibonacci calculation: {err}") from err
        try:
            sequence.append(next_fib)
        except Exception as err:
            print(f"Error appending next Fibonacci number: {err}")
            return sequence
    return sequence

