def caesar_cipher_encrypt(text, shift):
    if not isinstance(text, str):
        try:
            raise TypeError("Input 'text' must be a string.")
        except TypeError as err:
            return f"Error: {err}"

    try:
        if not isinstance(shift, int):
            raise TypeError("Input 'shift' must be an integer.")
    except TypeError as err:
        return f"Error: {err}"

    encrypted_text = []
    for char in text:
        if 'a' <= char <= 'z':
            try:
                shifted_char_code = ord('a') + (ord(char) - ord('a' + shift)) % 26
            except TypeError as err:
                return f"Error during character code calculation: {err}"
            except Exception as err:
                return f"Unexpected error during lowercase shift: {err}"
            encrypted_text.append(chr(shifted_char_code))
        elif 'A' <= char <= 'Z':
            try:
                shifted_char_code = ord('A') + (ord(char) - ord('A') + shift) % 26
            except ValueError as err:
                return f"Error during uppercase character conversion: {err}"
            except Exception as err:
                return f"Unexpected error during uppercase shift: {err}"
            encrypted_text.append(chr(shifted_char_code))
        else:
            try:
                encrypted_text.append(char)
            except Exception as err:
                return f"Error appending non-alphabetic character: {err}"

    try:
        return "".join(encrypted_text)
    except TypeError as err:
        return f"Error joining encrypted characters: {err}"
    except Exception as err:
        return f"Unexpected error during final join: {err}"

