def validate_email(email):
    try:
        if not isinstance(email, str):
            raise TypeError("Email must be a string.")
    except TypeError as err:
        print(f"Error: {err}")
        return False

    try:
        at_index = email.find('@')
        if at_index == -1:
            raise ValueError("Email must contain an '@' symbol.")
    except ValueError as err:
        print(f"Error: {err}")
        return False

    try:
        dot_index = email.find('.', at_index)
        if dot_index == -1:
            raise ValueError("Email must contain a '.' after the '@' symbol.")
    except ValueError as err:
        print(f"Error: {err}")
        return False

    try:
        if at_index > dot_index:
            raise ValueError("The '@' symbol must appear before the '.' symbol.")
    except ValueError as err:
        print(f"Error: {err}")
        return False

    try:
        if at_index == 0:
            raise ValueError("Email cannot start with '@'.")
    except ValueError as err:
        print(f"Error: {err}")
        return False

    try:
        if dot_index == len(email) - 1:
            raise ValueError("Email cannot end with '.'.")
    except ValueError as err:
        print(f"Error: {err}")
        return False

    return True

