def capitalize_sentences(text):
    try:
        if not isinstance(text, str):
            raise TypeError("Input must be a string.")
    except TypeError as err:
        print(f"Error: {err}")
        return ""

    sentences = []
    current_sentence_start = 0
    try:
        for i, char in enumerate(text):
            try:
                if char in ['.', '!', '?']:
                    sentences.append(text[current_sentence_start:i+1].strip())
                    current_sentence_start = i + 1
            except IndexError as err:
                print(f"Error accessing character at index {i}: {err}")
                return ""
    except Exception as err:
        print(f"Unexpected error during sentence splitting: {err}")
        return ""

    if current_sentence_start < len(text):
        try:
            remaining_text = text[current_sentence_start:].strip()
            if remaining_text:
                sentences.append(remaining_text)
        except Exception as err:
            print(f"Error processing remaining text: {err}")
            return ""

    capitalized_sentences = []
    try:
        for sentence in sentences:
            try:
                if sentence:
                    capitalized_sentences.append(sentence[0].upper() + sentence[1:])
                else:
                    capitalized_sentences.append("")
            except IndexError as err:
                print(f"Error capitalizing empty sentence: {err}")
                capitalized_sentences.append("")
            except Exception as err:
                print(f"Error capitalizing sentence '{sentence}': {err}")
                capitalized_sentences.append(sentence)
    except Exception as err:
        print(f"Unexpected error during sentence capitalization: {err}")
        return ""

    try:
        return ' '.join(capitalized_sentences)
    except Exception as err:
        print(f"Error joining sentences: {err}")
        return ""

