import re

def extract_hashtags(text):
    if not isinstance(text, str):
        try:
            raise TypeError("Input must be a string.")
        except TypeError as err:
            print(f"Error: {err}")
            return []

    try:
        if not text:
            return []
    except ValueError as err:
        print(f"Error checking for empty text: {err}")
        return []

    try:
        # Use regex to find all words starting with '#'
        raw_hashtags = re.findall(r'#(\w+)', text)
    except re.error as err:
        print(f"Regex error encountered: {err}")
        return []

    cleaned_hashtags = []
    for tag in raw_hashtags:
        try:
            if not isinstance(tag, str):
                raise TypeError("Expected string for tag processing.")
        except TypeError as err:
            print(f"Error processing tag type: {err}")
            continue
        try:
            # Additional cleaning if necessary (though \w+ handles most cases)
            cleaned_tag = tag.strip()
        except AttributeError as err:
            print(f"Error stripping tag: {err}")
            continue
        try:
            if cleaned_tag:
                cleaned_hashtags.append(cleaned_tag)
        except Exception as err:
            print(f"Error appending tag: {err}")
            continue
    try:
        return cleaned_hashtags
    except Exception as err:
        print(f"Error returning final list: {err}")
        return []

