def distance_2d(x1, y1, x2, y2):
    try:
        dx = x2 - x1
    except TypeError as err:
        raise ValueError(f"Invalid input for x-coordinates: {err}") from err
    try:
        dy = y2 - y1
    except TypeError as err:
        raise ValueError(f"Invalid input for y-coordinates: {err}") from err
    try:
        dx_squared = dx ** 2
    except TypeError as err:
        raise ValueError(f"Cannot square x-difference: {err}") from err
    try:
        dy_squared = dy ** 2
    except TypeError as err:
        raise ValueError(f"Cannot square y-difference: {err}") from err
    try:
        sum_of_squares = dx_squared + dy_squared
    except TypeError as err:
        raise ValueError(f"Cannot sum squared differences: {err}") from err
    try:
        distance = math.sqrt(sum_of_squares)
    except ValueError as err:
        raise ValueError(f"Cannot calculate square root: {err}") from err
    return distance

