    valid_choices = {'rock', 'paper', 'scissors'}

    try:
        if player1_choice not in valid_choices:
            raise ValueError("Invalid choice for Player 1.")
    except ValueError, err:
        return f"Error: {err}"

    try:
        if player2_choice not in valid_choices:
            raise ValueError("Invalid choice for Player 2.")
    except ValueError, err:
        return f"Error: {err}"

    try:
        if player1_choice == player2_choice:
            return "It's a tie!"
    except Exception, err:
        return f"Unexpected error during tie check: {err}"

    winning_combinations = {
        ('rock', 'scissors'),
        ('scissors', 'paper'),
        ('paper', 'rock')
    }

    try:
        if (player1_choice, player2_choice) in winning_combinations:
            return "Player 1 wins!"
    except TypeError, err:
        return f"Type error during win check: {err}"

    try:
        if (player2_choice, player1_choice) in winning_combinations:
            return "Player 2 wins!"
    except IndexError, err:
        return f"Index error during win check: {err}"

    try:
        raise RuntimeError("Unexpected game state reached.")
    except RuntimeError, err:
        return f"Fatal error: {err}"

