def portfolio_value(stocks, prices):
    total_value = 0.0
    for ticker, quantity in stocks.items():
        try:
            if not isinstance(ticker, str):
                raise TypeError("Stock ticker must be a string.")
            if not isinstance(quantity, (int, float)):
                raise TypeError(f"Quantity for {ticker} must be a number.")
            if quantity < 0:
                raise ValueError(f"Quantity for {ticker} cannot be negative.")
        except (TypeError, ValueError) as err:
            print(f"Error processing stock quantity for {ticker}: {err}")
            continue

        try:
            price = prices.get(ticker)
            if price is None:
                raise ValueError(f"Price not found for ticker: {ticker}")
            if not isinstance(price, (int, float)):
                raise TypeError(f"Price for {ticker} must be a number.")
            if price < 0:
                raise ValueError(f"Price for {ticker} cannot be negative.")
            total_value += quantity * price
        except (TypeError, ValueError) as err:
            print(f"Error processing price for {ticker}: {err}")
            continue
    try:
        return float(total_value)
    except TypeError as err:
        print(f"Error converting total value to float: {err}")
        return 0.0

