        print(f"Error: {err}")
        return None

    try:
        second_largest = unique_numbers[1]
    except IndexError as err:
        print(f"Error: Could not access the second element. {err}")
        return None
    except Exception as err:
        print(f"An unexpected error occurred when accessing the element: {err}")
        return None

    return second_largest

