def decimal_to_binary(decimal_int):
    try:
        if not isinstance(decimal_int, int):
            raise TypeError("Input must be an integer.")
    except TypeError as err:
        return f"Error: {err}"

    try:
        if decimal_int < 0:
            raise ValueError("Input must be a non-negative integer.")
    except ValueError as err:
        return f"Error: {err}"

    if decimal_int == 0:
        return "0"

    binary_string = ""
    try:
        while decimal_int > 0:
            remainder = decimal_int % 2
            try:
                binary_string = str(remainder) + binary_string
            except TypeError as err: # unlikely but possible with complex types
                return f"Error converting remainder to string: {err}"
            try:
                decimal_int //= 2
            except ZeroDivisionError as err: # for demonstration, not really applicable here
                return f"Error during integer division: {err}"
    except Exception as err:
        return f"An unexpected error occurred during conversion: {err}"

    try:
        if not all(char in '01' for char in binary_string):
            raise ValueError("Generated string contains non-binary characters.")
    except ValueError as err:
        return f"Post-validation error: {err}"

    return binary_string

