import math

def calculate_std_dev(numbers):
    try:
        n = len(numbers)
    except TypeError as err:
        print(f"Error: numbers must be a list or tuple. {err}")
        return None

    try:
        if n < 2:
            raise ValueError("At least two numbers are required to calculate standard deviation.")
    except ValueError as err:
        print(f"Error: {err}")
        return None

    try:
        mean = sum(numbers) / n
    except TypeError as err:
        print(f"Error: All elements in numbers must be numeric. {err}")
        return None
    except ZeroDivisionError as err:
        print(f"Error: Cannot calculate mean of an empty list. {err}")
        return None

    try:
        variance = sum([(x - mean) ** 2 for x in numbers]) / (n - 1)
    except TypeError as err:
        print(f"Error: Numeric operations failed during variance calculation. {err}")
        return None
    except ZeroDivisionError as err:
        print(f"Error: Cannot calculate variance with only one number. {err}")
        return None

    try:
        std_dev = math.sqrt(variance)
    except ValueError as err:
        print(f"Error: Cannot calculate square root of a negative variance. {err}")
        return None
    except TypeError as err:
        print(f"Error: math.sqrt received an invalid type. {err}")
        return None

    return std_dev

