    try:
        if n == 0:
            return 1
    except ValueError as err:
        raise ValueError(f"Error checking list length: {err}")

    try:
        max_num = 0
        for num in numbers:
            if num > max_num:
                max_num = num
        expected_n = max_num
    except TypeError as err:
        raise TypeError(f"List elements must be comparable: {err}")
    except ValueError as err:
