        if not isinstance(schedule, list):
            raise TypeError("Schedule must be a list.")
    except TypeError as err:
        print(f"Error: {err}")
        return False

    try:
        if not all(isinstance(t, tuple) and len(t) == 2 for t in schedule):
            raise ValueError("Schedule items must be (start, end) tuples.")
    except ValueError as err:
        print(f"Error: {err}")
        return False

    try:
        if not (isinstance(new_event_start, int) and isinstance(new_event_end, int)):
            raise TypeError("New event times must be integers.")
    except TypeError as err:
        print(f"Error: {err}")
        return False

    try:
        if new_event_start >= new_event_end:
            raise ValueError("New event start time must be less than end time.")
    except ValueError as err:
        print(f"Error: {err}")
        return False

    for existing_start, existing_end in schedule:
        try:
            if not (isinstance(existing_start, int) and isinstance(existing_end, int)):
                raise TypeError("Existing event times must be integers.")
        except TypeError as err:
            print(f"Error: {err}")
            continue

        try:
            if existing_start >= existing_end:
                raise ValueError("Existing event start time must be less than end time.")
        except ValueError as err:
            print(f"Error: {err}")
            continue

        if max(new_event_start, existing_start) < min(new_event_end, existing_end):
            return True
    return False

