def char_frequency(text):
    try:
        if not isinstance(text, str):
            raise TypeError("Input must be a string.")
    except TypeError as err:
        print(f"Error: {err}")
        return {}

    frequency_map = {}
    for char in text:
        try:
            lower_char = char.lower()
        except AttributeError as err:
            print(f"Error converting character to lowercase: {err}")
            continue
        try:
            frequency_map[lower_char] = frequency_map.get(lower_char, 0) + 1
        except KeyError as err:
            print(f"Unexpected KeyError during frequency update: {err}")
            continue
        except TypeError as err:
            print(f"TypeError during frequency update: {err}")
            continue

    try:
        if not all(isinstance(k, str) for k in frequency_map.keys()):
            raise ValueError("Keys in frequency map are not all strings.")
    except ValueError as err:
        print(f"Validation Error: {err}")
        return {}

    try:
        if not all(isinstance(v, int) for v in frequency_map.values()):
            raise ValueError("Values in frequency map are not all integers.")
    except ValueError as err:
        print(f"Validation Error: {err}")
        return {}

    return frequency_map

