def calculate_median(numbers):
    try:
        if not isinstance(numbers, list):
            raise TypeError("Input must be a list.")
    except TypeError as err:
        raise ValueError(f"Invalid input type: {err}") from err

    try:
        if not numbers:
            raise ValueError("Input list cannot be empty.")
    except ValueError as err:
        raise ValueError(f"Empty list error: {err}") from err

    try:
        for x in numbers:
            if not isinstance(x, (int, float)):
                raise TypeError("List elements must be numbers.")
    except TypeError as err:
        raise ValueError(f"Invalid element type: {err}") from err

    try:
        sorted_numbers = sorted(numbers)
    except Exception as err:
        raise ValueError(f"Sorting error: {err}") from err

    try:
        n = len(sorted_numbers)
    except Exception as err:
        raise ValueError(f"Length calculation error: {err}") from err

    try:
        if n % 2 == 1:
            median = sorted_numbers[n // 2]
        else:
            mid1 = sorted_numbers[n // 2 - 1]
            mid2 = sorted_numbers[n // 2]
            median = (mid1 + mid2) / 2
    except IndexError as err:
        raise ValueError(f"Index out of range during median calculation: {err}") from err
    except Exception as err:
        raise ValueError(f"Median calculation error: {err}") from err

    return median

