def is_armstrong(number):
    try:
        if not isinstance(number, int):
            raise TypeError("Input must be an integer.")
    except TypeError as err:
        print(f"Error: {err}")
        return False

    try:
        if number < 0:
            raise ValueError("Input must be a positive integer.")
    except ValueError as err:
        print(f"Error: {err}")
        return False

    try:
        num_str = str(number)
    except Exception as err:
        print(f"Error converting number to string: {err}")
        return False

    try:
        num_digits = len(num_str)
    except Exception as err:
        print(f"Error getting number of digits: {err}")
        return False

    armstrong_sum = 0
    for digit_char in num_str:
        try:
            digit = int(digit_char)
            armstrong_sum += digit ** num_digits
        except ValueError as err:
            print(f"Error converting character to digit: {err}")
            return False
        except TypeError as err:
            print(f"Error during power calculation: {err}")
            return False

    try:
        return armstrong_sum == number
    except Exception as err:
        print(f"Error comparing sum and number: {err}")
        return False

