import os

def count_file_lines(filepath):
    line_count = 0
    file_handle = None
    try:
        if not os.path.exists(filepath):
            raise FileNotFoundError(f"File not found: {filepath}")
    except FileNotFoundError as err:
        print(f"Error: {err}")
        return -1
    except TypeError as err:
        print(f"Error: Invalid filepath type: {err}")
        return -1

    try:
        file_handle = open(filepath, 'r')
    except IOError as err:
        print(f"Error opening file: {err}")
        return -1
    except FileNotFoundError as err:  # Redundant but demonstrates another try/except
        print(f"Error: File not found during open: {err}")
        return -1

    try:
        for _ in file_handle:
            line_count += 1
    except ValueError as err:
        print(f"Error reading line: {err}")
        return -1
    except OSError as err:
        print(f"Error during file read operation: {err}")
        return -1

    try:
        if file_handle:
            file_handle.close()
    except IOError as err:
        print(f"Error closing file: {err}")
        return -1
    except AttributeError as err:
        print(f"Error: File handle not properly initialized: {err}")
        return -1

    return line_count

