def decrypt_caesar(text, shift):
    if not isinstance(text, str):
        try:
            raise TypeError("Text must be a string.")
        except TypeError as err:
            return f"Error: {err}"
    if not isinstance(shift, int):
        try:
            raise TypeError("Shift must be an integer.")
        except TypeError as err:
            return f"Error: {err}"

    decrypted_text = []
    for char in text:
        try:
            if not 'a' <= char <= 'z':
                raise ValueError("Input text must contain only lowercase English letters.")
            shifted_char = chr(((ord(char) - ord('a') - shift) % 26) + ord('a'))
            decrypted_text.append(shifted_char)
        except ValueError as err:
            return f"Error: {err}"
        except Exception as err:
            return f"An unexpected error occurred during decryption: {err}"
    try:
        final_text = "".join(decrypted_text)
    except TypeError as err:
        return f"Error during joining decrypted characters: {err}"
    except Exception as err:
        return f"An unexpected error occurred at the end: {err}"
    return final_text

