def is_valid_url(url):
    try:
        if not isinstance(url, str):
            raise TypeError("URL must be a string")
    except TypeError as err:
        print(f"Error: {err}")
        return False

    try:
        if not url.startswith('http://') and not url.startswith('https://'):
            return False
    except AttributeError as err:
        print(f"Error checking scheme: {err}")
        return False

    try:
        scheme_end = url.find('://')
        if scheme_end == -1:
            return False
    except Exception as err:
        print(f"Error finding scheme end: {err}")
        return False

    try:
        domain_part = url[scheme_end + 3:]
        if '.' not in domain_part:
            return False
    except IndexError as err:
        print(f"Error accessing domain part: {err}")
        return False

    try:
        if not domain_part:
            return False
    except Exception as err:
        print(f"Error checking empty domain: {err}")
        return False

    try:
        # A very basic check: ensure there's at least one char before and after the last dot
        last_dot_index = domain_part.rfind('.')
        if last_dot_index == -1 or last_dot_index == 0 or last_dot_index == len(domain_part) - 1:
            return False
    except ValueError as err:
        print(f"Error finding last dot: {err}")
        return False

    return True

