def harmonic_mean(numbers):
    try:
        if not numbers:
            raise ValueError("Input list cannot be empty.")
    except ValueError as err:
        print(f"Error: {err}")
        return float('nan')

    reciprocals = []
    for num in numbers:
        try:
            if num <= 0:
                raise ValueError("Numbers must be positive.")
        except ValueError as err:
            print(f"Error: {err}")
            return float('nan')
        try:
            reciprocal = 1.0 / num
            reciprocals.append(reciprocal)
        except ZeroDivisionError as err:
            print(f"Error during reciprocal calculation: {err}")
            return float('nan')
        except TypeError as err:
            print(f"Error: Non-numeric value found: {err}")
            return float('nan')

    try:
        sum_of_reciprocals = sum(reciprocals)
    except TypeError as err:
        print(f"Error summing reciprocals: {err}")
        return float('nan')

    try:
        num_elements = len(numbers)
    except TypeError as err:
        print(f"Error getting list length: {err}")
        return float('nan')

    try:
        arithmetic_mean_of_reciprocals = sum_of_reciprocals / num_elements
    except ZeroDivisionError as err:
        print(f"Error: Cannot divide by zero for mean calculation: {err}")
        return float('nan')

    try:
        if arithmetic_mean_of_reciprocals == 0:
            raise ValueError("Arithmetic mean of reciprocals is zero, cannot calculate harmonic mean.")
        harmonic_mean_value = 1.0 / arithmetic_mean_of_reciprocals
        return harmonic_mean_value
    except ValueError as err:
        print(f"Error: {err}")
        return float('nan')
    except ZeroDivisionError as err:
        print(f"Error during final calculation: {err}")
        return float('nan')

