def simulate_stack(stack, operation, item=None):
    try:
        if not isinstance(stack, list):
            raise TypeError("Stack must be a list.")
    except TypeError as err:
        print(f"Error: {err}")
        return None

    try:
        operation = operation.lower()
    except AttributeError as err:
        print(f"Error converting operation to lowercase: {err}")
        return None

    if operation == 'push':
        try:
            stack.append(item)
        except AttributeError as err:
            print(f"Error appending to stack: {err}")
            return None
        return stack
    elif operation == 'pop':
        try:
            if not stack:
                return None
        except ValueError as err:
            print(f"Error checking if stack is empty: {err}")
            return None
        try:
            popped_item = stack.pop()
        except IndexError as err:
            print(f"Error popping from empty stack: {err}")
            return None
        return popped_item
    else:
        try:
            raise ValueError("Invalid operation. Use 'push' or 'pop'.")
        except ValueError as err:
            print(f"Error: {err}")
            return None

