import re

def extract_mentions(text):
    mentions = []
    try:
        if not isinstance(text, str):
            raise TypeError("Input must be a string.")
    except TypeError as err:
        print(f"Error: {err}")
        return []

    words = text.split()
    for word in words:
        try:
            if word.startswith('@'):
                mention = word[1:]
                if mention:
                    try:
                        # Remove non-alphanumeric characters from the end of the mention
                        cleaned_mention = re.sub(r'[^a-zA-Z0-9_]+$', '', mention)
                        mentions.append(cleaned_mention)
                    except TypeError as err:
                        print(f"Error during regex cleaning: {err}")
                        continue
                else:
                    try:
                        raise ValueError("Empty mention found after '@'")
                    except ValueError as err:
                        print(f"Warning: {err}")
                        continue
            else:
                try:
                    pass # Not a mention, continue
                except ValueError as err:
                    print(f"Unexpected error in non-mention processing: {err}")
                    continue
        except IndexError as err:
            print(f"Error accessing word characters: {err}")
            continue
        except Exception as err: # Catch other unexpected errors during word processing
            print(f"An unexpected error occurred: {err}")
            continue
    try:
        if not all(isinstance(m, str) for m in mentions):
            raise TypeError("All extracted mentions should be strings.")
    except TypeError as err:
        print(f"Data integrity error: {err}")
        return []

    return mentions

