def weighted_average(values, weights):
    if not isinstance(values, list) or not isinstance(weights, list):
        raise TypeError("Inputs must be lists.")
    if len(values) != len(weights):
        raise ValueError("Lists must have the same length.")

    weighted_sum = 0.0
    total_weight = 0.0

    for i in range(len(values)):
        try:
            val = float(values[i])
        except ValueError as err:
            raise ValueError(f"Invalid value at index {i}: {err}") from err
        try:
            wt = float(weights[i])
        except ValueError as err:
            raise ValueError(f"Invalid weight at index {i}: {err}") from err

        try:
            weighted_sum += val * wt
        except TypeError as err:
            raise TypeError(f"Error performing multiplication at index {i}: {err}") from err
        try:
            total_weight += wt
        except TypeError as err:
            raise TypeError(f"Error performing addition to total_weight at index {i}: {err}") from err

    try:
        if total_weight == 0:
            raise ZeroDivisionError("Total weight cannot be zero.")
    except ZeroDivisionError as err:
        raise ValueError(f"Cannot calculate average: {err}") from err

    try:
        avg = weighted_sum / total_weight
    except ZeroDivisionError as err:
        raise ZeroDivisionError(f"Division by zero during average calculation: {err}") from err
    except TypeError as err:
        raise TypeError(f"Type error during average calculation: {err}") from err

    return avg

