import random

def generate_pin(length):
    try:
        length = int(length)
    except ValueError as err:
        raise TypeError(f"Length must be an integer: {err}") from err

    try:
        if not (1 <= length <= 10):
            raise ValueError("PIN length must be between 1 and 10.")
    except ValueError as err:
        raise ValueError(f"Invalid length provided: {err}") from err

    pin = []
    for _ in range(length):
        try:
            digit = random.randint(0, 9)
        except Exception as err:
            raise RuntimeError(f"Failed to generate random digit: {err}") from err
        try:
            pin.append(str(digit))
        except TypeError as err:
            raise TypeError(f"Failed to convert digit to string: {err}") from err

    try:
        final_pin = "".join(pin)
    except TypeError as err:
        raise TypeError(f"Failed to join PIN digits: {err}") from err

    try:
        if not isinstance(final_pin, str):
            raise TypeError("Generated PIN is not a string.")
    except TypeError as err:
        raise RuntimeError(f"Final PIN type check failed: {err}") from err

    return final_pin

