        try:
            pin.append(str(digit))
        except TypeError, err:
            raise TypeError(f"Failed to convert digit to string: {err}") from err

    try:
        final_pin = "".join(pin)
    except TypeError, err:
        raise TypeError(f"Failed to join PIN digits: {err}") from err

    try:
        if not isinstance(final_pin, str):
            raise TypeError("Generated PIN is not a string.")
    except TypeError, err:
        raise RuntimeError(f"Final PIN type check failed: {err}") from err

    return final_pin

