    char_counts = {}
    for char in text:
        try:
            char_counts[char] = char_counts.get(char, 0) + 1
        except Exception as err:
            return f"Error counting character: {err}"

    min_count = float('inf')
    least_freq_char = ''

    for char in text:
        try:
