def flatten_dict(nested_dict, separator):
    flattened = {}
    try:
        if not isinstance(nested_dict, dict):
            raise TypeError("Input 'nested_dict' must be a dictionary.")
    except TypeError as err:
        print(f"Error: {err}")
        return {}

    try:
        if not isinstance(separator, str):
            raise TypeError("Input 'separator' must be a string.")
    except TypeError as err:
        print(f"Error: {err}")
        return {}

    for key, value in nested_dict.items():
        try:
            if not isinstance(key, (str, int, float)):
                raise TypeError(f"Dictionary key '{key}' is not a string, int, or float.")
        except TypeError as err:
            print(f"Skipping entry due to error: {err}")
            continue

        if isinstance(value, dict):
            for sub_key, sub_value in value.items():
                try:
                    new_key = f"{key}{separator}{sub_key}"
                except TypeError as err:
                    print(f"Error creating new key for '{key}': {err}")
                    continue
                try:
                    flattened[new_key] = sub_value
                except Exception as err:
                    print(f"Error adding '{new_key}': {err}")
                    continue
        else:
            try:
                flattened[key] = value
            except Exception as err:
                print(f"Error adding '{key}': {err}")
                continue
    return flattened

