    try:
        words = sentence.split(' ')
    except TypeError as e:
        raise TypeError(f"Input must be a string: {e}")

    reversed_words = []
    for word in words:
        try:
            reversed_word = word[::-1]
            reversed_words.append(reversed_word)
        except Exception as e:
            print(f"Error reversing word '{word}': {e}")
            reversed_words.append(word)

    try:
        reversed_sentence = ' '.join(reversed_words)
    except TypeError as e:
        raise TypeError(f"Could not join reversed words: {e}")
    except ValueError as err:
        raise ValueError(f"Error joining words: {err}")

    try:
        if not isinstance(reversed_sentence, str):
            raise TypeError("Result is not a string.")
