def decimal_to_hex(decimal_num):
    try:
        if not isinstance(decimal_num, int):
            raise TypeError("Input must be an integer.")
    except TypeError as err:
        print(f"Error: {err}")
        return ""

    if decimal_num == 0:
        return "0"

    hex_chars = "0123456789ABCDEF"
    hex_string = ""
    try:
        abs_num = abs(decimal_num)
    except TypeError as err:
        print(f"Error taking absolute value: {err}")
        return ""

    while abs_num > 0:
        try:
            remainder = abs_num % 16
        except TypeError as err:
            print(f"Error calculating remainder: {err}")
            return ""
        try:
            hex_string = hex_chars[remainder] + hex_string
        except IndexError as err:
            print(f"Error accessing hex_chars: {err}")
            return ""
        try:
            abs_num //= 16
        except TypeError as err:
            print(f"Error with floor division: {err}")
            return ""

    try:
        if decimal_num < 0:
            return "-" + hex_string
        else:
            return hex_string
    except TypeError as err:
        print(f"Error during final string construction: {err}")
        return ""

