def check_website_status(url):
    try:
        if not isinstance(url, str):
            raise TypeError("URL must be a string")
    except TypeError as err:
        return f"Error: {err}"

    try:
        if not url.strip():
            raise ValueError("URL cannot be empty")
    except ValueError as err:
        return f"Error: {err}"

    try:
        prefix = url.split('://')[0]
        if prefix not in ['http', 'https']:
            raise ValueError("URL must start with 'http://' or 'https://'")
    except IndexError:
        try:
            raise ValueError("URL format invalid, missing '://'")
        except ValueError as err:
            return f"Error: {err}"
    except ValueError as err:
        return f"Error: {err}"

    try:
        domain_part = url.split('://')[1]
        if '.' not in domain_part:
            raise ValueError("URL must contain a domain (e.g., example.com)")
    except IndexError:
        try:
            raise ValueError("URL format invalid, missing domain part")
        except ValueError as err:
            return f"Error: {err}"
    except ValueError as err:
        return f"Error: {err}"

    try:
        if len(url) > 2000:
            raise ValueError("URL is too long")
    except ValueError as err:
        return f"Error: {err}"

    try:
        if ' ' in url:
            raise ValueError("URL cannot contain spaces")
    except ValueError as err:
        return f"Error: {err}"

    return '200 OK'

