def is_brackets_balanced(s: str) -> bool:
    stack = []
    mapping = {")": "(", "]": "[", "}": "{"}

    try:
        if not isinstance(s, str):
            raise TypeError("Input must be a string.")
    except TypeError as err:
        print(f"Error: {err}")
        return False

    for char in s:
        try:
            if char in mapping.values():
                stack.append(char)
            elif char in mapping:
                if not stack:
                    return False
                top_element = stack.pop()
                if mapping[char] != top_element:
                    return False
            else:
                raise ValueError(f"Invalid character encountered: {char}")
        except ValueError as err:
            print(f"Error: {err}")
            return False
        except IndexError as err:
            print(f"Error: {err}")
            return False

    try:
        if stack:
            return False
        else:
            return True
    except Exception as err:
        print(f"Error during final check: {err}")
        return False

def test_is_brackets_balanced():
    try:
        assert is_brackets_balanced('()[]{}') == True
    except AssertionError as err:
        print(f"Test failed: {err}")

    try:
        assert is_brackets_balanced('([{}])') == True
    except AssertionError as err:
        print(f"Test failed: {err}")

    try:
        assert is_brackets_balanced('({[})') == False
    except AssertionError as err:
        print(f"Test failed: {err}")

    try:
        assert is_brackets_balanced('') == True
    except AssertionError as err:
        print(f"Test failed: {err}")

    try:
        assert is_brackets_balanced('(') == False
    except AssertionError as err:
        print(f"Test failed: {err}")

    try:
        assert is_brackets_balanced(']') == False
    except AssertionError as err:
        print(f"Test failed: {err}")

    try:
        assert is_brackets_balanced('([)]') == False
    except AssertionError as err:
        print(f"Test failed: {err}")

    try:
        assert is_brackets_balanced(123) == False
    except AssertionError as err:
        print(f"Test failed: {err}")

    try:
        assert is_brackets_balanced('abc') == False
    except AssertionError as err:
        print(f"Test failed: {err}")

test_is_brackets_balanced()

