def has_overlap(meeting1, meeting2):
    try:
        s1, e1 = meeting1
    except ValueError as err:
        raise ValueError(f"Invalid meeting1 format: {err}") from err
    try:
        s2, e2 = meeting2
    except ValueError as err:
        raise ValueError(f"Invalid meeting2 format: {err}") from err

    try:
        s1 = int(s1)
        e1 = int(e1)
    except ValueError as err:
        raise ValueError(f"Meeting1 times must be integers: {err}") from err

    try:
        s2 = int(s2)
        e2 = int(e2)
    except ValueError as err:
        raise ValueError(f"Meeting2 times must be integers: {err}") from err

    try:
        if s1 > e1:
            raise ValueError("Meeting1 start time must be before end time.")
