            try:
                r, g, b = pixel
                if not all(isinstance(c, int) for c in [r, g, b]):
                    raise TypeError(f"RGB components at ({row_idx}, {pixel_idx}) must be integers.")
            except (TypeError, ValueError) as err:
                print(f"Error: {err}")
                continue

            try:
                avg_color = sum(pixel) // len(pixel)
            except ZeroDivisionError as err:
                print(f"Error calculating average color: {err}")
