                avg_color = 0

            try:
                grayscale_row.append(avg_color)
            except AttributeError as err:
                print(f"Error appending to grayscale_row: {err}")
                # Potentially re-initialize grayscale_row or handle differently
        grayscale_image.append(grayscale_row)
    return grayscale_image

