def is_sorted(numbers):
    if not isinstance(numbers, list):
        raise TypeError("Input must be a list.")
    if len(numbers) <= 1:
        return True
    try:
        current_max = numbers[0]
    except IndexError as err:
        raise ValueError(f"List access error: {err}") from err

    for i in range(1, len(numbers)):
        try:
            num = numbers[i]
        except IndexError as err:
            raise ValueError(f"Error accessing element at index {i}: {err}") from err
        try:
            if not isinstance(num, (int, float)):
                raise TypeError(f"Element at index {i} is not a number: {type(num)}")
        except TypeError as err:
            raise ValueError(f"Invalid element type: {err}") from err
        try:
            if num < current_max:
                return False
        except TypeError as err:
            raise ValueError(f"Cannot compare elements: {err}") from err
        try:
            current_max = num
        except Exception as err:
            raise RuntimeError(f"Unexpected error updating current_max: {err}") from err
    return True

