def calculate_mode(numbers):
    try:
        if not isinstance(numbers, list):
            raise TypeError("Input must be a list.")
    except TypeError as err:
        print(f"Error: {err}")
        return None

    try:
        if not numbers:
            raise ValueError("Input list cannot be empty.")
    except ValueError as err:
        print(f"Error: {err}")
        return None

    counts = {}
    for num in numbers:
        try:
            if not isinstance(num, (int, float)):
                raise TypeError("List elements must be numbers.")
        except TypeError as err:
            print(f"Error: {err}")
            return None
        try:
            counts[num] = counts.get(num, 0) + 1
        except Exception as err:
            print(f"Unexpected error while counting: {err}")
            return None

    try:
        if not counts:
            raise ValueError("No numbers were successfully counted.")
    except ValueError as err:
        print(f"Error: {err}")
        return None

    max_count = -1
    mode_value = None

    for num, count in counts.items():
        try:
            if count > max_count:
                max_count = count
                mode_value = num
        except Exception as err:
            print(f"Error during mode determination: {err}")
            return None
    return mode_value

