import datetime

def days_between_dates(start_date_str, end_date_str):
    try:
        start_date = datetime.datetime.strptime(start_date_str, '%Y-%m-%d').date()
    except ValueError as err:
        raise ValueError(f"Invalid start date format: {err}")
    except TypeError as err:
        raise TypeError(f"Start date must be a string: {err}")

    try:
        end_date = datetime.datetime.strptime(end_date_str, '%Y-%m-%d').date()
    except ValueError as err:
        raise ValueError(f"Invalid end date format: {err}")
    except TypeError as err:
        raise TypeError(f"End date must be a string: {err}")

    try:
        delta = end_date - start_date
    except TypeError as err:
        raise TypeError(f"Date objects cannot be subtracted: {err}")

    try:
        return delta.days
    except AttributeError as err:
        raise AttributeError(f"Date difference object has no 'days' attribute: {err}")
    except Exception as err:
        raise Exception(f"An unexpected error occurred while getting days: {err}")

