def calculate_simple_interest(principal, rate, time):
    try:
        p_val = float(principal)
    except ValueError as err:
        raise ValueError(f"Invalid principal: {err}")

    try:
        r_val = float(rate)
    except ValueError as err:
        raise ValueError(f"Invalid rate: {err}")

    try:
        t_val = int(time)
    except ValueError as err:
        raise ValueError(f"Invalid time: {err}")

    try:
        if p_val < 0:
            raise ValueError("Principal cannot be negative.")
