        raise ValueError(f"Principal error: {err}")

    try:
        if r_val < 0:
            raise ValueError("Rate cannot be negative.")
    except ValueError as err:
        raise ValueError(f"Rate error: {err}")

    try:
        if t_val < 0:
            raise ValueError("Time cannot be negative.")
    except ValueError as err:
        raise ValueError(f"Time error: {err}")

    interest = (p_val * r_val * t_val) / 100
    return float(interest)

