def hex_to_decimal(hex_string):
    try:
        if not isinstance(hex_string, str):
            raise TypeError("Input must be a string.")
    except TypeError as err:
        print(f"Error: {err}")
        return None

    try:
        if not hex_string:
            raise ValueError("Input string cannot be empty.")
    except ValueError as err:
        print(f"Error: {err}")
        return None

    decimal_value = 0
    try:
        power = 0
    except Exception as err:
        print(f"Unexpected error initializing power: {err}")
        return None

    for char in reversed(hex_string):
        try:
            char_upper = char.upper()
        except AttributeError as err:
            print(f"Error converting char to upper: {err}")
            return None

        try:
            if '0' <= char_upper <= '9':
                digit = int(char_upper)
            elif 'A' <= char_upper <= 'F':
                digit = ord(char_upper) - ord('A') + 10
            else:
                raise ValueError(f"Invalid hexadecimal character: {char}")
        except ValueError as err:
            print(f"Error processing character '{char}': {err}")
            return None
        except TypeError as err:
            print(f"Type error during character processing: {err}")
            return None

        try:
            decimal_value += digit * (16 ** power)
        except OverflowError as err:
            print(f"Error: Number too large for integer representation: {err}")
            return None
        except TypeError as err:
            print(f"Type error during calculation: {err}")
            return None

        try:
            power += 1
        except Exception as err:
            print(f"Unexpected error incrementing power: {err}")
            return None

    return decimal_value

