def is_valid_luhn(card_number):
    try:
        if not isinstance(card_number, str):
            raise TypeError("Input must be a string.")
    except TypeError as err:
        print(f"Error: {err}")
        return False

    total_sum = 0
    num_digits = len(card_number)

    for i, char_digit in enumerate(card_number):
        try:
            digit = int(char_digit)
        except ValueError as err:
            print(f"Error converting character to digit: {err}")
            return False

        try:
            if not (0 <= digit <= 9):
                raise ValueError("Digit out of range (0-9).")
        except ValueError as err:
            print(f"Error: {err}")
            return False

        try:
            if (num_digits - 1 - i) % 2 == 1:
                doubled_digit = digit * 2
                if doubled_digit > 9:
                    total_sum += (doubled_digit - 9)
                else:
                    total_sum += doubled_digit
            else:
                total_sum += digit
        except Exception as err:
            print(f"Error during sum calculation: {err}")
            return False

    try:
        if total_sum % 10 == 0:
            return True
        else:
            return False
    except ZeroDivisionError as err:
        print(f"Error during modulo operation: {err}")
        return False
    except Exception as err:
        print(f"Unexpected error in final check: {err}")
        return False

