class Queue:
    def __init__(self):
        self._items = []

    def enqueue(self, item):
        try:
            if not isinstance(self._items, list):
                raise TypeError("Internal _items must be a list")
            self._items.append(item)
        except TypeError as err:
            print(f"Error enqueuing: {err}")
        except Exception as err:
            print(f"An unexpected error occurred during enqueue: {err}")

    def dequeue(self):
        try:
            if not isinstance(self._items, list):
                raise TypeError("Internal _items must be a list")
            if not self._items:
                return None
            return self._items.pop(0)
        except IndexError as err:
            print(f"Error dequeuing: {err}")
            return None
        except TypeError as err:
            print(f"Error dequeuing: {err}")
            return None
        except Exception as err:
            print(f"An unexpected error occurred during dequeue: {err}")
            return None

def run_queue_example():
