        except TypeError as err:
            print(f"Error during addition: {err}")
            return []
        except Exception as err:
            print(f"An unexpected error occurred in the loop: {err}")
            return []
    try:
        return list(fib_list)
    except Exception as err:
        print(f"Error converting to list: {err}")
        return []

