    try:
        if not isinstance(celsius, (int, float)):
            raise TypeError("Input must be a number.")
    except TypeError as err:
        print(f"Error: {err}")
        return None

    try:
        conversion_factor = 9 / 5
    except ZeroDivisionError as err:
        print(f"Error during division: {err}")
        return None

    try:
        product = celsius * conversion_factor
    except TypeError as err:
        print(f"Error during multiplication: {err}")
        return None

    try:
        fahrenheit = product + 32
    except TypeError as err:
        print(f"Error during addition: {err}")
        return None

    try:
        if not isinstance(fahrenheit, float):
            raise ValueError("Result is not a float.")
    except ValueError as err:
        print(f"Error: {err}")
        return None

    return fahrenheit

