def encrypt_shift(text, shift):
    result = []
    for char in text:
        try:
            if not isinstance(char, str):
                raise TypeError("Input characters must be strings.")
            if 'a' <= char <= 'z':
                shifted_char_code = ord('a') + (ord(char) - ord('a' ) + shift) % 26
                result.append(chr(shifted_char_code))
            elif 'A' <= char <= 'Z':
                shifted_char_code = ord('A') + (ord(char) - ord('A') + shift) % 26
                result.append(chr(shifted_char_code))
            else:
                result.append(char)
        except TypeError as err:
            result.append(f"Error: {err}")
        except ValueError as err:
            result.append(f"Error processing character: {err}")
    try:
        if not all(isinstance(r, str) for r in result):
            raise TypeError("Result contains non-string elements.")
        final_string = "".join(result)
        return final_string
    except TypeError as err:
        return f"Finalization Error: {err}"
    except ValueError as err:
        return f"Finalization Error: {err}"
    except Exception as err:
        return f"Unknown Finalization Error: {err}"

