def calculate_compound_interest(principal, rate, compounding_frequency, time_years):
    try:
        if not isinstance(principal, (int, float)):
            raise TypeError("Principal must be a number.")
    except TypeError as err:
        print(f"Error: {err}")
        return None

    try:
        if not isinstance(rate, (int, float)):
            raise TypeError("Rate must be a number.")
    except TypeError as err:
        print(f"Error: {err}")
        return None

    try:
        if not isinstance(compounding_frequency, int):
            raise TypeError("Compounding frequency must be an integer.")
    except TypeError as err:
        print(f"Error: {err}")
        return None

    try:
        if not isinstance(time_years, int):
            raise TypeError("Time in years must be an integer.")
    except TypeError as err:
        print(f"Error: {err}")
        return None

    try:
        if principal < 0:
            raise ValueError("Principal cannot be negative.")
    except ValueError as err:
        print(f"Error: {err}")
        return None

    try:
        if rate < 0:
            raise ValueError("Rate cannot be negative.")
    except ValueError as err:
        print(f"Error: {err}")
        return None

    try:
        if compounding_frequency <= 0:
            raise ValueError("Compounding frequency must be positive.")
    except ValueError as err:
        print(f"Error: {err}")
        return None

    try:
        if time_years <= 0:
            raise ValueError("Time in years must be positive.")
    except ValueError as err:
        print(f"Error: {err}")
        return None

    try:
        amount = principal * (1 + rate / compounding_frequency)**(compounding_frequency * time_years)
    except Exception as err:
        print(f"An unexpected error occurred during calculation: {err}")
