def parse_url_params(query_string):
    params = {}
    try:
        if not isinstance(query_string, str):
            raise TypeError("Query string must be a string")
    except TypeError as err:
        print(f"Error: {err}")
        return {}

    try:
        pairs = query_string.split('&')
    except AttributeError as err:
        print(f"Error splitting query string: {err}")
        return {}

    for pair in pairs:
        try:
            if not pair:
                continue
        except Exception as err:
            print(f"Unexpected error checking pair: {err}")
            continue

        try:
            parts = pair.split('=', 1)
        except AttributeError as err:
            print(f"Error splitting pair: {err}")
            continue

        try:
            if len(parts) == 2:
                key = parts[0]
                value = parts[1]
            elif len(parts) == 1:
                key = parts[0]
                value = ""
            else:
                raise ValueError(f"Invalid pair format: {pair}")
        except ValueError as err:
            print(f"Error processing pair '{pair}': {err}")
            continue
        except IndexError as err:
            print(f"Index error for pair '{pair}': {err}")
            continue

        try:
            params[key] = value
        except Exception as err:
            print(f"Error assigning to dictionary: {err}")
            continue

    return params

