def multiply_2x2_matrices(matrix_a, matrix_b):
    try:
        if not isinstance(matrix_a, list) or len(matrix_a) != 2:
            raise ValueError("matrix_a must be a 2-element list")
    except ValueError as err:
        print(f"Error: {err}")
        return None

    try:
        if not isinstance(matrix_b, list) or len(matrix_b) != 2:
            raise ValueError("matrix_b must be a 2-element list")
    except ValueError as err:
        print(f"Error: {err}")
        return None

    result = [[0, 0], [0, 0]]

    for i in range(2):
        try:
            if not isinstance(matrix_a[i], list) or len(matrix_a[i]) != 2:
                raise ValueError(f"matrix_a row {i} must be a 2-element list")
        except ValueError as err:
            print(f"Error: {err}")
            return None

        for j in range(2):
            try:
                if not isinstance(matrix_b[j], list) or len(matrix_b[j]) != 2:
                    raise ValueError(f"matrix_b row {j} must be a 2-element list")
            except ValueError as err:
                print(f"Error: {err}")
                return None

            try:
                if not isinstance(matrix_a[i][0], (int, float)):
                    raise ValueError(f"matrix_a[{i}][0] must be a number")
            except ValueError as err:
                print(f"Error: {err}")
                return None

            try:
                if not isinstance(matrix_a[i][1], (int, float)):
                    raise ValueError(f"matrix_a[{i}][1] must be a number")
            except ValueError as err:
                print(f"Error: {err}")
                return None

            result[i][j] = (matrix_a[i][0] * matrix_b[0][j] +
                            matrix_a[i][1] * matrix_b[1][j])
    return result

