def calculate_sma(data, window_size):
    try:
        if not isinstance(data, list):
            raise TypeError("Data must be a list.")
    except TypeError as err:
        print(f"Error: {err}")
        return []

    try:
        if not all(isinstance(x, (int, float)) for x in data):
            raise TypeError("All data points must be numbers.")
    except TypeError as err:
        print(f"Error: {err}")
        return []

    try:
        if not isinstance(window_size, int):
            raise TypeError("Window size must be an integer.")
    except TypeError as err:
        print(f"Error: {err}")
        return []

    try:
        if window_size <= 0:
            raise ValueError("Window size must be positive.")
    except ValueError as err:
        print(f"Error: {err}")
        return []

    try:
        if window_size > len(data):
            raise ValueError("Window size cannot be greater than the number of data points.")
    except ValueError as err:
        print(f"Error: {err}")
        return []

    sma = []
    for i in range(len(data) - window_size + 1):
        try:
            window_sum = sum(data[i:i + window_size])
            average = window_sum / window_size
            sma.append(float(average))
        except ZeroDivisionError as err:
            print(f"Error during calculation: {err}")
            return []
        except Exception as err:
            print(f"An unexpected error occurred: {err}")
            return []
    return sma

