def roman_to_int(roman_numeral):
    roman_map = {'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100, 'D': 500, 'M': 1000}
    try:
        if not isinstance(roman_numeral, str):
            raise TypeError("Input must be a string.")
    except TypeError as err:
        print(f"Error: {err}")
        return None

    try:
        num = 0
        prev_value = 0
    except Exception as err:
        print(f"Unexpected error during initialization: {err}")
        return None

    for char in reversed(roman_numeral):
        try:
            value = roman_map[char]
        except KeyError as err:
            print(f"Error: Invalid Roman numeral character '{err}'.")
            return None
        except Exception as err:
            print(f"Unexpected error getting character value: {err}")
            return None

        try:
            if value < prev_value:
                num -= value
            else:
                num += value
            prev_value = value
        except Exception as err:
            print(f"Error during value comparison/addition: {err}")
            return None

    try:
        if not (1 <= num <= 3999):
            raise ValueError("Resulting integer is out of the valid range (1-3999).")
    except ValueError as err:
        print(f"Error: {err}")
        return None
    except Exception as err:
        print(f"Unexpected error during final range check: {err}")
        return None

    return num

