def generate_primes(n):
    try:
        if not isinstance(n, int):
            raise TypeError("Input must be an integer.")
    except TypeError as err:
        print(f"Error: {err}")
        return []

    try:
        if n < 2:
            return []
    except ValueError as err:
        print(f"Error checking n < 2: {err}")
        return []

    primes = []
    try:
        for num in range(2, n + 1):
            is_prime = True
            try:
                if num < 2:
                    is_prime = False
            except ValueError as err:
                print(f"Error checking num < 2: {err}")
                is_prime = False

            try:
                for i in range(2, int(num**0.5) + 1):
                    try:
                        if num % i == 0:
                            is_prime = False
                            break
                    except ZeroDivisionError as err:
                        print(f"Error during division check: {err}")
                        is_prime = False
                        break
            except ValueError as err:
                print(f"Error in square root calculation: {err}")
                is_prime = False

            try:
                if is_prime:
                    primes.append(num)
            except Exception as err:
                print(f"Error appending prime number: {err}")
    except Exception as err:
        print(f"Error during prime generation loop: {err}")
        return []
    return primes

