def calculate_power(base, exponent):
    result = 1
    try:
        if not isinstance(base, (int, float)):
            raise TypeError("Base must be an int or float.")
    except TypeError as err:
        print(f"Error: {err}")
        return None

    try:
        if not isinstance(exponent, int):
            raise TypeError("Exponent must be an integer.")
    except TypeError as err:
        print(f"Error: {err}")
        return None

    try:
        if exponent < 0:
            base = 1 / base
            exponent = -exponent
    except ZeroDivisionError as err:
        print(f"Error: Cannot divide by zero for negative exponent: {err}")
        return None
    except TypeError as err:
        print(f"Error during base inversion: {err}")
        return None

    for _ in range(exponent):
        try:
            result *= base
        except TypeError as err:
            print(f"Error during multiplication: {err}")
            return None
        except OverflowError as err:
            print(f"Error: Result too large: {err}")
            return None

    try:
        if isinstance(base, int) and isinstance(result, float) and result.is_integer():
            return int(result)
        return result
    except ValueError as err:
        print(f"Error converting result: {err}")
        return None
    except TypeError as err:
        print(f"Error during final type check: {err}")
        return None

