import math

def calculate_sphere_volume(radius):
    try:
        if not isinstance(radius, (int, float)):
            raise TypeError("Radius must be a number.")
    except TypeError as err:
        print(f"Error: {err}")
        return None

    try:
        radius = float(radius)
    except ValueError as err:
        print(f"Error converting radius to float: {err}")
        return None

    try:
        if radius < 0:
            raise ValueError("Radius cannot be negative.")
    except ValueError as err:
        print(f"Error: {err}")
        return None

    try:
        pi_val = math.pi
    except AttributeError as err:
        print(f"Error accessing math.pi: {err}")
        return None

    try:
        radius_cubed = radius ** 3
    except TypeError as err:
        print(f"Error cubing radius: {err}")
        return None

    try:
        volume = (4/3) * pi_val * radius_cubed
    except ZeroDivisionError as err:
        print(f"Error during division: {err}")
        return None
    except TypeError as err:
        print(f"Error calculating volume: {err}")
        return None

    return volume

