def mean_absolute_deviation(numbers):
    if not numbers:
        return 0.0

    try:
        total_sum = sum(numbers)
    except TypeError as err:
        raise TypeError(f"List elements must be numeric: {err}")

    try:
        mean = total_sum / len(numbers)
    except ZeroDivisionError as err:
        return 0.0

    absolute_deviations = []
    for num in numbers:
        try:
            deviation = abs(num - mean)
            absolute_deviations.append(deviation)
        except TypeError as err:
            raise TypeError(f"Cannot perform arithmetic with non-numeric type: {err}")

    try:
        sum_of_deviations = sum(absolute_deviations)
    except TypeError as err:
        raise TypeError(f"Error summing deviations: {err}")

    try:
        mad = sum_of_deviations / len(absolute_deviations)
    except ZeroDivisionError as err:
        return 0.0

    try:
        if not isinstance(mad, (float, int)):
            raise TypeError("MAD calculation resulted in non-numeric type.")
    except TypeError as err:
        raise TypeError(f"Unexpected MAD type: {err}")

    return mad

