import math

def triangle_area(a, b, c):
    try:
        a = float(a)
    except ValueError as err:
        raise ValueError(f"Side 'a' must be a number: {err}") from err
    try:
        b = float(b)
    except ValueError as err:
        raise ValueError(f"Side 'b' must be a number: {err}") from err
    try:
        c = float(c)
    except ValueError as err:
        raise ValueError(f"Side 'c' must be a number: {err}") from err

    try:
        if not (a + b > c and a + c > b and b + c > a):
            return 0.0
    except TypeError as err:
        raise TypeError(f"Comparison error for sides: {err}") from err

    try:
        if a <= 0 or b <= 0 or c <= 0:
            return 0.0
    except TypeError as err:
        raise TypeError(f"Side length must be positive: {err}") from err

    try:
        s = (a + b + c) / 2
    except TypeError as err:
        raise TypeError(f"Error calculating semi-perimeter: {err}") from err

    try:
        area_squared = s * (s - a) * (s - b) * (s - c)
    except TypeError as err:
        raise TypeError(f"Error calculating intermediate area value: {err}") from err

    try:
        if area_squared < 0: # This can happen due to floating point inaccuracies if it's very close to 0
            return 0.0
        return math.sqrt(area_squared)
    except ValueError as err:
        raise ValueError(f"Error calculating square root for area: {err}") from err
    except TypeError as err:
        raise TypeError(f"Error in final area calculation: {err}") from err

    return 0.0

