import math

def geometric_mean(numbers):
    try:
        if not isinstance(numbers, list):
            raise TypeError("Input must be a list.")
    except TypeError as err:
        print(f"Error: {err}")
        return 0.0

    try:
        if not numbers:
            return 0.0
    except Exception as err:
        print(f"Unexpected error checking list emptiness: {err}")
        return 0.0

    product = 1.0
    count = 0

    for x in numbers:
        try:
            if not isinstance(x, (int, float)):
                raise TypeError("List elements must be numbers.")
        except TypeError as err:
            print(f"Error: {err}")
            return 0.0

        try:
            if x <= 0:
                return 0.0
        except Exception as err:
            print(f"Unexpected error checking number positivity: {err}")
            return 0.0
        product *= x
        count += 1

    try:
        if count == 0:
            return 0.0
    except Exception as err:
        print(f"Unexpected error after loop: {err}")
        return 0.0

    try:
        return product ** (1 / count)
    except ZeroDivisionError as err:
        print(f"Error: {err} - count should not be zero here.")
        return 0.0
    except Exception as err:
        print(f"Unexpected error calculating geometric mean: {err}")
        return 0.0

