def levenshtein_distance(s1, s2):
    try:
        if not isinstance(s1, str) or not isinstance(s2, str):
            raise TypeError("Both inputs must be strings.")
    except TypeError as err:
        print(f"Error: {err}")
        return -1

    try:
        len_s1 = len(s1)
    except TypeError as err:
        print(f"Error getting length of s1: {err}")
        return -1
    try:
        len_s2 = len(s2)
    except TypeError as err:
        print(f"Error getting length of s2: {err}")
        return -1

    try:
        dp = [[0] * (len_s2 + 1) for _ in range(len_s1 + 1)]
    except MemoryError as err:
        print(f"Error creating DP table: {err}")
        return -1

    try:
        for i in range(len_s1 + 1):
            dp[i][0] = i
    except IndexError as err:
        print(f"Error initializing column: {err}")
        return -1

    try:
        for j in range(len_s2 + 1):
            dp[0][j] = j
    except IndexError as err:
        print(f"Error initializing row: {err}")
        return -1

    for i in range(1, len_s1 + 1):
        for j in range(1, len_s2 + 1):
            try:
                cost = 0 if s1[i-1] == s2[j-1] else 1
            except IndexError as err:
                print(f"Error accessing string characters: {err}")
                return -1
            try:
                dp[i][j] = min(dp[i-1][j] + 1,      # Deletion
                               dp[i][j-1] + 1,      # Insertion
                               dp[i-1][j-1] + cost) # Substitution
            except ValueError as err:
                print(f"Error during min calculation: {err}")
                return -1
            except IndexError as err:
                print(f"Error accessing DP table during update: {err}")
                return -1
    try:
        return dp[len_s1][len_s2]
    except IndexError as err:
        print(f"Error retrieving final result: {err}")
        return -1

