def convert_base(number, base):
    digits = "0123456789ABCDEF"
    try:
        if not isinstance(number, int):
            raise TypeError("Number must be an integer.")
    except TypeError as err:
        raise ValueError(f"Invalid input: {err}") from err

    try:
        if not (2 <= base <= 16):
            raise ValueError("Base must be between 2 and 16.")
    except ValueError as err:
        raise ValueError(f"Invalid base: {err}") from err

    if number == 0:
        return "0"

    result = []
    try:
        temp_number = abs(number)
    except TypeError as err:
        raise ValueError(f"Cannot process number: {err}") from err

    while temp_number > 0:
        try:
            remainder = temp_number % base
        except TypeError as err:
            raise ValueError(f"Modulo operation failed: {err}") from err
        try:
            result.append(digits[remainder])
        except IndexError as err:
            raise ValueError(f"Digit mapping failed: {err}") from err
        try:
            temp_number //= base
        except TypeError as err:
            raise ValueError(f"Integer division failed: {err}") from err

    if number < 0:
        result.append('-')
    return "".join(result[::-1])

