    if not isinstance(n, int):
        try:
            raise TypeError("Input must be an integer")
        except TypeError as err:
            print(f"Error: {err}")
            return None

    try:
        if n < 0:
            raise ValueError("Input must be a non-negative integer")
    except ValueError as err:
        print(f"Error: {err}")
        return None

    count = 0
    temp_n = n
    while temp_n > 0:
        try:
            if not isinstance(temp_n, int):
                raise TypeError("Internal error: temp_n is not an integer")
        except TypeError as err:
            print(f"Error during bit counting: {err}")
            return None

        try:
            count += (temp_n & 1)
        except Exception as err:
            print(f"Error during bitwise AND: {err}")
            return None

        try:
            temp_n >>= 1
        except Exception as err:
            print(f"Error during bit shift: {err}")
