        has_digit = any(c.isdigit() for c in password)
    except AttributeError as err:
        return f"Error checking digit. {err}"

    conditions_met = 0
    try:
        if has_upper:
            conditions_met += 1
        if has_lower:
            conditions_met += 1
        if has_digit:
            conditions_met += 1
    except Exception as err:
        return f"Error counting conditions. {err}"

    if length >= 8 and has_upper and has_lower and has_digit:
        return 'Strong'
    elif length >= 6 and conditions_met >= 2:
        return 'Medium'
    else:
        try:
            return 'Weak'
        except Exception as err:
            return f"Error determining weakness. {err}"

