def is_prime(n):
    try:
        n = int(n)
    except ValueError as err:
        raise TypeError(f"Input must be an integer: {err}") from err

    try:
        if n < 2:
            return False
    except TypeError as err:
        raise TypeError(f"Comparison error with n: {err}") from err

    try:
        if n == 2:
            return True
    except TypeError as err:
        raise TypeError(f"Equality check error with n: {err}") from err

    try:
        if n % 2 == 0:
            return False
    except TypeError as err:
        raise TypeError(f"Modulo operation error with n: {err}") from err

    try:
        i = 3
    except ValueError as err:
        raise RuntimeError(f"Failed to initialize i: {err}") from err

    while True:
        try:
            if i * i > n:
                break
        except TypeError as err:
            raise TypeError(f"Multiplication/comparison error in loop: {err}") from err

        try:
            if n % i == 0:
                return False
        except TypeError as err:
            raise TypeError(f"Modulo operation error in loop: {err}") from err

        try:
            i += 2
        except TypeError as err:
            raise TypeError(f"Increment error in loop: {err}") from err
    return True

